/* From Uiverse.io by csozidev - Tags: loading, loader, smooth, text animation, animated, wave, text, infinite */
/* Wave text loader made by: csozi | Website: english.csozi.hu*/

.__UIV_SCOPE__ .text {
  color: black;
  font-weight: bolder;
}

@keyframes letter {
  0% {
    font-size: 30px;
  }

  50% {
    font-size: 40px;
  }

  100% {
    font-size: 30px;
  }
}

.__UIV_SCOPE__ .letter {
  animation: letter 1s infinite;
}

.__UIV_SCOPE__ .letter1 {
  animation-delay: 0s;
}

.__UIV_SCOPE__ .letter2 {
  animation-delay: -0.9s;
}

.__UIV_SCOPE__ .letter3 {
  animation-delay: -0.8s;
}

.__UIV_SCOPE__ .letter4 {
  animation-delay: -0.7s;
}

.__UIV_SCOPE__ .letter5 {
  animation-delay: -0.6s;
}

.__UIV_SCOPE__ .letter6 {
  animation-delay: -0.5s;
}

.__UIV_SCOPE__ .letter7 {
  animation-delay: -0.4s;
}

.__UIV_SCOPE__ .letter8 {
  animation-delay: -0.3s;
}

.__UIV_SCOPE__ .letter9 {
  animation-delay: -0.2s;
}

.__UIV_SCOPE__ .letter10 {
  animation-delay: -0.1s;
}
